-- ---- M816-01 Projektregistrierung ----
-- M816-01.investment_type
update public.fields set verification_status='verified_against_standard', verification_quote='Aktuelle Investitionen sind zumeist auf den Ersatz- und die Erneuerung vorhandener wasserwirtschaftlicher Anlagen fokussiert. | Das Merkblatt ist eine Weiterentwicklung der KVR-Leitlinien mit der Projektbewertung betrieblicher Er-satz- und Erneuerungsinvestitionen auf Basis der dynamischen Kostenvergleichsrechnung mittels Allgemeiner Rentenbarwertfaktoren. — printed p.12', verification_note='md-verified 2026-09-05 (§1 Anwendungsbereich, printed p.12) [VC]', verified_at=now() where id='5d1c25f9-8d47-478a-a5f8-3e920c0e9431' and verification_status not in ('verified_against_standard','corrected');
-- M816-01.evaluation_basis
update public.fields set verification_status='verified_against_standard', verification_quote='Der derzeitigen Fassung der KVR-Leitlinien liegt das „Prinzip der Realbewertung“, d. h. der Verwendung von realen (inflationsbereinigten) Zahlungen anstelle nominaler (preisindizierter) Zahlungen, zugrunde. | Jedoch erst die nominalwertige Zahlungsverfolgung nach Projektbeginn und Gegenüberstellung nominal erfasster Kosten im Projektzahlungsplan und in der Projektkostenverfolgung ermöglichen eine vergleichende Nachkontrolle und darüber Erkenntnisse für künftige Investitionen. — printed p.18', verification_note='md-verified 2026-09-05 (§3.2.1 (page ref = first fragment; second fragment §1 p.12), printed p.18) [VC]', verified_at=now() where id='7eb824a2-1a5e-4e32-b779-6384e6b62914' and verification_status not in ('verified_against_standard','corrected');
-- M816-01.ust_treatment
update public.fields set verification_status='verified_against_standard', verification_quote='Herkömmlich wird die Abwasserbeseitigung durch abwasserbeseitigungspflichtige juristische Personen des öffentlichen Rechts als nicht umsatzsteuerbarer Umsatz im Hoheitsbereich angesehen. Die in die Wirtschaftlichkeitsrechnung eingehenden Zahlungen sind somit brutto, ohne den Abzug von Vorsteuern, zu berücksichtigen. | Bei gewerblichen Investitionsprojekten außerhalb hoheitlicher Betätigung sind aufgrund der sogenannte Vorsteuerabzugsfähigkeit nun alle betrieblichen und investiven Beschaffungen nicht mehr mit ihren Bruttobeträgen, sondern nur noch netto ohne Mehrwertsteuer anzusetzen. — printed p.94', verification_note='md-verified 2026-09-05 (§6.2 Umsatzsteuern (second fragment §4.5.4 p.42), printed p.94) [VC]', verified_at=now() where id='b4ceb64a-b76b-4579-afb9-de2120b0923b' and verification_status not in ('verified_against_standard','corrected');
-- M816-01.methodology_confirmation
update public.fields set verification_status='verified_against_standard', verification_quote='Die Wirtschaftlichkeitsrechnung unterscheidet hinsichtlich des Zeitfaktors zwischen der stark vereinfachten statischen Kostenvergleichsrechnung und der den zeitlichen Anfall von Zahlungen berücksichtigenden dynamischen Kostenvergleichsrechnung. | Das Berechnungsschema ist für alle Anwendungen immer gleich: erst werden die relevanten Zahlungsprozesse einer Projektalternative identifiziert, mittels geeigneter Zahlungsfunktionen abgebildet und schließlich auf dieser Basis direkt mittels der ARBF in Form eines Barwerts bewertet. — printed p.17', verification_note='md-verified 2026-09-05 (§3.1 (second fragment §4.1.1 p.21), printed p.17) [VC]', verified_at=now() where id='8f840249-2444-4011-9510-97871fe2ca47' and verification_status not in ('verified_against_standard','corrected');

-- ---- M816-02 Definition der Investitionsalternativen ----
-- M816-02.alternative_count
update public.fields set verification_status='verified_against_standard', verification_quote='Der einer Wirtschaftlichkeitsberechnung zugrunde zu legende Betrachtungszeitraum wird jedoch in der Regel von mehreren zu vergleichenden Investitionsalternativen geprägt. | Wesentlich ist hier, dass für alle in Betracht gezogenen Projektalternativen die gleiche Diskontierungsregel zur Anwendung kommt. — printed p.38', verification_note='md-verified 2026-09-05 (§4.4.1 (second fragment §4.2.1 p.31), printed p.38) [VC]', verified_at=now() where id='c973308f-7c7e-419a-8a2e-22934c4364d5' and verification_status not in ('verified_against_standard','corrected');
-- M816-02.partial_replication_flag
update public.fields set verification_status='verified_against_standard', verification_quote='Ein Lösungsansatz ist die sog. Teilreplikation. Diese versucht durch eine Teilwiederholung der kürzeren Alternative bis zum Ende der längeren Alternative wirtschaftlich einen gemeinsamen Planungshorizont herzustellen. | In der Praxis stellt sich häufig das Problem, dass aufgrund unterschiedlicher Nutzungsdauern der Investitionen, also zum Beispiel $n_{\mathrm{A}}=30$ Jahre $>n_{\mathrm{B}}=25$ Jahre, die zu vergleichenden Alternativen zunächst unterschiedliche Betrachtungszeiträume aufweisen. — printed p.38', verification_note='md-verified 2026-09-05 (§4.4.1, printed p.38) [VC]', verified_at=now() where id='00b96344-fb1b-4034-af08-08fd59660f33' and verification_status not in ('verified_against_standard','corrected');
-- M816-02.alternatives
update public.fields set verification_status='verified_against_standard', verification_quote='Im Rahmen der Vergleichsberechnungen werden zwei Alternativen untersucht. | Der einer Wirtschaftlichkeitsberechnung zugrunde zu legende Betrachtungszeitraum wird jedoch in der Regel von mehreren zu vergleichenden Investitionsalternativen geprägt. — printed p.48', verification_note='md-verified 2026-09-05 (§5.2.3 (second fragment §4.4.1 p.38), printed p.48) [VC] — caveat: the register schema (Kennung + Bezeichnung) is EKOWAI’s; the guideline only requires that the compared alternatives be defined and described', verified_at=now() where id='5ba33ca8-318b-41cc-97c1-59fc24ead00a' and verification_status not in ('verified_against_standard','corrected');

-- ---- M816-03 Datenquelle und Methodenwahl ----
-- M816-03.data_source_type
update public.fields set verification_status='verified_against_standard', verification_quote='Eine Orientierung zur Bestimmung der Nutzungsdauer einer Anlage bzw. von Anlagenteilen bieten die Angaben der Hersteller. Dies hat seine Grenzen dort, wo eine Anlage komplex und von unterschiedlichen Lieferanteilen und damit häufig auch unterschiedlichen Herstellern geprägt ist. Eine weitere Orientierung bieten durchschnittliche Nutzungsdauern von vergleichbaren Anlagen. Hier liefern die KVR-Leitlinien branchenbezogene Tabellen (z. B. für Baugewerbe und Maschinenbau). — printed p.38', verification_note='md-verified 2026-09-05 (§4.4.1, printed p.38) [VC]', verified_at=now() where id='7643060f-6a5e-484b-ae9f-bba7fd9e6c4f' and verification_status not in ('verified_against_standard','corrected');
-- M816-03.investment_method
update public.fields set verification_status='verified_against_standard', verification_quote='Darüber hinaus bietet die dynamische Kostenvergleichsrechnung auf Basis der Bewertung von Zahlungsprozessen mittels Allgemeiner Rentenbarwertfaktoren gegenüber den KVR-Leitlinien die Möglichkeit zur Abbildung nicht konstanter Kostenverläufe. | Die KVR-Leitlinien empfehlen - losgelöst von Laufzeiten, Zinstrends und Zinsschwankungen am Kapitalmarkt - die dauerhafte Anwendung eines einheitlichen realen Zinssatzes von 3 \% p. a. für Zwecke der Abzinsung. — printed p.12', verification_note='md-verified 2026-09-05 (§1 (second fragment §4.2.1 p.31), printed p.12) [VC]', verified_at=now() where id='0ddead98-cbdd-4795-b849-20453a8b4cdb' and verification_status not in ('verified_against_standard','corrected');
-- M816-03.cost_index_reference
update public.fields set verification_status='verified_against_standard', verification_quote='Formal erfolgt die Preisindexierung der einzelnen Zahlungsprozesse $Z(t)$ mittels der jeweiligen spezifischen, nominalen Preissteigerungsrate $p \%$, um dann ausgehend von der Formulierung in GI. (4a) explizit Zahlungsfunktionen mit Inflationsberücksichtigung zu erhalten: | Der WBZW eines Anlageguts für ein bestimmtes Berichtsjahr kann als inflationierter AHK nach dem Indexverfahren, nach dem Mengenverfahren oder einer Kombination dieser beiden Bewertungsverfahren ermittelt werden. — printed p.28', verification_note='md-verified 2026-09-05 (§4.1.6 (second fragment §4.5.3 p.40), printed p.28) [VC] — caveat: M816 works with a per-process Preissteigerungsrate p%, not with a named external cost index; the "Kostenindex-Referenz" free-text field is EKOWAI’s wrapper', verified_at=now() where id='5ca3a14c-0ee5-40e3-ae15-3033a21193e3' and verification_status not in ('verified_against_standard','corrected');

-- ---- M816-04 Finanzmarktparameter ----
-- M816-04.discounting_method
update public.fields set verification_status='verified_against_standard', verification_quote='Die KVR-Leitlinien empfehlen - losgelöst von Laufzeiten, Zinstrends und Zinsschwankungen am Kapitalmarkt - die dauerhafte Anwendung eines einheitlichen realen Zinssatzes von 3 \% p. a. für Zwecke der Abzinsung. | Geeigneter erscheint daher vor allem unter dem Gesichtspunkt der Langfristigkeit wasserwirtschaftlicher Maßnahmen die Verwendung der monatlich von der Deutschen Bundesbank veröffentlichten Abzinsungszinssätze $i_{\mathrm{t}}$ für Laufzeiten $t$ von 1 bis 50 Jahren, wie in Bild 7 dargestellt. | statt der aktuellen Bundesbank-Abzinsungszinssätze ist dann jeweils ein Null-Zinssatz - aus mathematischen Gründen nicht exakt Null, sondern z.B. 0,001 \% anzusetzen. — printed p.31', verification_note='md-verified 2026-09-05 (§4.2.1, printed p.31) [VC]', verified_at=now() where id='9c80bd38-02e3-4130-b3b6-25bd5173e8fa' and verification_status not in ('verified_against_standard','corrected');
-- M816-04.bundesbank_reference_date
update public.fields set verification_status='verified_against_standard', verification_quote='Die Deutsche Bundesbank veröffentlicht monatlich Abzinsungszinssätze gemäß § 253 Abs. 2 HGB. Sie sind gemäß des ab 2009 in Kraft getretenen Bilanzrechtsmodernisierungsgesetzes (BilMoG) in Verbindung mit der Rückstellungsabzinsungsverordnung (RückAbzinsV) verbindlich für die Abzinsung von langfristigen Zahlungsverpflichtungen im Bereich der bilanziellen Rückstellungsermittlung anzuwenden. | Nachfolgend werden bei allen Berechnungen jeweils die Bundesbank-Abzinsungs-Zinssätze zum 31.12.2017 verwendet. — printed p.18', verification_note='md-verified 2026-09-05 (§3.2.4 (second fragment §4.2.1 p.31), printed p.18) [VC]', verified_at=now() where id='9d0126a5-f7b0-4144-a5f6-774575c45891' and verification_status not in ('verified_against_standard','corrected');
-- M816-04.kvr_base_rate
update public.fields set verification_status='verified_against_standard', verification_quote='Die KVR-Leitlinien empfehlen hier aus praktischen Erwägungen die Anwendung eines realen Zinssatzes von einheitlich $3 \%$ p. a. | Die KVR-Leitlinien empfehlen - losgelöst von Laufzeiten, Zinstrends und Zinsschwankungen am Kapitalmarkt - die dauerhafte Anwendung eines einheitlichen realen Zinssatzes von 3 \% p. a. für Zwecke der Abzinsung. — printed p.18', verification_note='md-verified 2026-09-05 (§3.2.4 (second fragment §4.2.1 p.31), printed p.18) [VC]', verified_at=now() where id='1855a08c-eb6c-4cba-a6fc-cf19096ffca7' and verification_status not in ('verified_against_standard','corrected');
-- M816-04.q_initial
update public.fields set verification_status='verified_against_standard', verification_quote='Für die weiteren Berechnungen in diesem Abschnitt wird zunächst vereinfachend ein einheitlicher Abzinsungszinssatz $i=3 \%$ bzw. Abzinsungsfaktor $q=i+1=1,03$ vorgegeben. | \hline $q$ & - & Abzinsungszinsfaktor für die Barwertermittlung $q=1+i$ \\ — printed p.21', verification_note='md-verified 2026-09-05 (§4.1.1 (second fragment §2 Formelzeichen p.13), printed p.21) [VC]', verified_at=now() where id='71a47024-663a-4d6c-b791-1b00b58156b1' and verification_status not in ('verified_against_standard','corrected');

