update public.fields set verification_status='verified_against_standard', verification_quote='In mehreren Bundesländern wird die Bezuschussung von wasserwirtschaftlichen Projekten davon abhängig gemacht, dass die Maßnahme auch ohne Zuschuss wirtschaftlich vorteilhaft ist (FöRiWWV). Somit ist eine zusätzliche Wirtschaftlichkeitsrechnung unter Vollfinanzierung der Investition durchzuführen; d. h. Zuschüsse oder Finanzierungshilfen dürfen nicht berücksichtigt werden. | Die Erstinvestition wird zu $30 \%$ aus Landesmitteln gefördert. — printed p.40', verification_note='md-verified 2026-09-05 (§4.5.2 (second fragment §4.7 p.44), printed p.40) [VC]', verified_at=now() where id='3b557a55-696e-4783-9e1d-940ccbc9aeb6' and verification_status not in ('verified_against_standard','corrected');
