update public.fields set verification_status='verified_against_standard', verification_quote='Für die Zentrifugen (Alternative 1) werden zusätzlich Kosten von 10.710 € (brutto) für die Durchführung einer im ca. 3-jährigen Rhythmus erforderlichen Werksrevision berücksichtigt. | \hline Revision Zentrifuge ca. 10.710,-/3a & €/a & 3.600 & \\ — printed p.58', verification_note='md-verified 2026-09-05 (§5.2.5 Kosten für Werksrevision / Tabelle 14, printed p.58) [VC]', verified_at=now() where id='d34882b7-3961-4976-9cf2-851109e4d1d4' and verification_status not in ('verified_against_standard','corrected');
-- M816-07.other_operating_costs_annual
update public.fields set verification_status='verified_against_standard', verification_quote='Bei den Betriebskosten werden aufgrund der Delta-Betrachtung der beiden Alternativen nur solche Kostenarten betrachtet, bei denen Unterschiede gegeben sind. Vorstehend sind lediglich die Kostenarten berücksichtigt worden, die sich durch die vorgesehene Umstellung der Verfahrensführung im Rahmen der Alternative 2 verändern. — printed p.88', verification_note='md-verified 2026-09-05 (§5.4.5.7 Übrige Betriebskosten, printed p.88) [VC]', verified_at=now() where id='bcab01ca-2bad-41d2-8eef-986a8b54634d' and verification_status not in ('verified_against_standard','corrected');
-- M816-07.total_operating_costs_annual
update public.fields set verification_status='verified_against_standard', verification_quote='Die Kosten für das Betreiben von Entwässerungsaggregaten setzen sich im Wesentlichen aus den nachfolgend aufgelisteten Komponenten zusammen: I Fällmittel: Kosten für Hilfsstoffe, hier Flockungsmittel, I Energie: Energiekosten, I Personal: Personalkosten für Betrieb und Wartung der Aggregate, I Revision: Werksrevision Alternative 1 (Zentrifuge). | Eine dynamische Kostenvergleichsrechnung, in der die Alternativen „Zentrifuge“ und „Bandeindicker“ gegenübergestellt werden, zeigt, welcher Aggregattyp unter Berücksichtigung der Investitions- und Betriebskosten letztendlich der wirtschaftlichere ist. — printed p.55', verification_note='md-verified 2026-09-05 (§5.2.5 Betriebskosten (second fragment §5.2.4 p.50), printed p.55) [VC]', verified_at=now() where id='32193d06-7cbe-4c90-978d-588dc7aef63f' and verification_status not in ('verified_against_standard','corrected');

-- ---- M816-08 Nutzungsdauer und Betrachtungszeitraum ----
-- M816-08.life_category
update public.fields set verification_status='verified_against_standard', verification_quote='die Betriebsphase wird in der Regel aus der Nutzungsdauer der Anlage bzw. des Anlagenteils bestimmt. Dabei wird zwischen der I betriebsgewöhnlichen Nutzungsdauer, I technischen (technisch max. mögliche) Nutzungsdauer, I wirtschaftlichen (wirtschaftlich erstrebenswerte) Nutzungsdauer, I steuerrechtlichen Nutzungsdauer unterschieden. In die Kostenvergleichsrechnung geht in der Regel die betriebsgewöhnliche Nutzungsdauer ein. — printed p.38', verification_note='md-verified 2026-09-05 (§4.4.1, printed p.38) [VC]', verified_at=now() where id='f4201040-5a49-4958-a636-e715aa92c302' and verification_status not in ('verified_against_standard','corrected');
-- M816-08.n_useful_life
update public.fields set verification_status='verified_against_standard', verification_quote='Der Betrachtungszeitraum einer Investitionsalternative richtet sich nach der Dauer der Investitionsund der Betriebsphase sowie der Nachlaufphase (z. B. Rückbau, Entsorgung). Die Investitionsphase umfasst die Planungs- und Bauzeit, die Betriebsphase wird in der Regel aus der Nutzungsdauer der Anlage bzw. des Anlagenteils bestimmt. | Für welche Nutzungsdauer sich der Betreiber einer wasserwirtschaftlichen Anlage entscheidet, hängt dabei wesentlich auch von der eigenen betrieblichen Erfahrung und der in der Anlagenbuchhaltung nach Anlagenklassen und Anlagennummern bereits abgebildeten Nutzungsdauer vorhandener, durch die Ersatz- und Erneuerungsinvestition zu ersetzender Anlagen bzw. Anlagenteile ab. — printed p.38', verification_note='md-verified 2026-09-05 (§4.4.1, printed p.38) [VC]', verified_at=now() where id='6b1a5a8e-0df1-492d-a702-77664bd9b999' and verification_status not in ('verified_against_standard','corrected');
-- M816-08.n_observation_period
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $n$ & Jahre & Anzahl der Jahre des Betrachtungszeitraums (Planungshorizonts) \\ | Es stellt sich dann die Frage, bis zu welchem gemeinsamen Planungshorizont müssen die beiden Alternativen verglichen werden? — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §4.4.1 p.38), printed p.13) [VC]', verified_at=now() where id='d1d035ad-c90d-493e-a00d-78c92c353596' and verification_status not in ('verified_against_standard','corrected');
-- M816-08.n_a
update public.fields set verification_status='verified_against_standard', verification_quote='In der Praxis stellt sich häufig das Problem, dass aufgrund unterschiedlicher Nutzungsdauern der Investitionen, also zum Beispiel $n_{\mathrm{A}}=30$ Jahre $>n_{\mathrm{B}}=25$ Jahre, die zu vergleichenden Alternativen zunächst unterschiedliche Betrachtungszeiträume aufweisen. — printed p.38', verification_note='md-verified 2026-09-05 (§4.4.1, printed p.38) [VC]', verified_at=now() where id='eafa0e4c-7ab9-463f-b770-329268f03996' and verification_status not in ('verified_against_standard','corrected');
-- M816-08.n_b
update public.fields set verification_status='verified_against_standard', verification_quote='In der Praxis stellt sich häufig das Problem, dass aufgrund unterschiedlicher Nutzungsdauern der Investitionen, also zum Beispiel $n_{\mathrm{A}}=30$ Jahre $>n_{\mathrm{B}}=25$ Jahre, die zu vergleichenden Alternativen zunächst unterschiedliche Betrachtungszeiträume aufweisen. | Bei der Teilreplikation wird die kürzere Alternative (B) entsprechend der Nutzungsdauerdifferenz zwischen langer und kurzer Alternative teilweise repliziert. — printed p.38', verification_note='md-verified 2026-09-05 (§4.4.1 (second fragment §4.4.2 p.39), printed p.38) [VC]', verified_at=now() where id='23ee0c69-ab6e-4b9c-ae04-620d21402e16' and verification_status not in ('verified_against_standard','corrected');

-- ---- M816-09 Inflation und Preisentwicklung ----
-- M816-09.p_percent
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $p \%$ & \% p. a. & Inflationsrate einer Kostengröße pro Jahr \\ | Auf lange Sicht erscheint eine Basisinflationsrate von $1,5 \%$ bis $2 \%$ ein guter Kompromiss zu sein. Diese Annahme bezieht ihre Rechtfertigung aus der Preisstabilitätsverpflichtung der Europäischen Zentralbank (EZB) bzw. der Bundesbank mit der Folge von Gegenmaßnahmen bei Verletzung des Inflationsziels: danach ist aus der Sicht der Notenbanken Preisstabilität dann gegeben, wenn die jährliche Preissteigerungsrate die $2 \%$-Marke nicht überschreitet. — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §4.1.6 p.28), printed p.13) [VC]', verified_at=now() where id='6d362fe7-a424-466a-813e-96e0fbfadcee' and verification_status not in ('verified_against_standard','corrected');
-- M816-09.p_factor
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $p$ & - & Inflationsfaktor $p=p \%+1$ einer Kostengröße \\ | Z(t)=\sum c_{k} \cdot t^{k} \cdot p^{t} \tag{5a} \end{equation*} $$ $$ t=1, \ldots, n \text { mit } p=1+p \% — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment Gl. 5a, §4.1.6 p.28), printed p.13) [VC]', verified_at=now() where id='9e8f8369-e78a-4585-b489-adee6436e47d' and verification_status not in ('verified_against_standard','corrected');
-- M816-09.p_v_percent
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $p_{\mathrm{v}}$ & - & Inflationsfaktor $p_{\mathrm{v}}=p_{\mathrm{v}} \%+1$ in der Vorlaufphase bis zu einer Reinvestition \\ | Allerdings wird nun nach einem Vorlauf von $v=15$ Jahren die entsprechende Reinvestition der damaligen ErstInvestition von 5 Mio. € unter Berücksichtigung einer zwischenzeitlichen Verteuerung von $p_{\mathrm{v}} \%=1,5 \%$ p. a. ( $p_{\mathrm{v}}=1,015$ ) in der Vorlaufphase finanziert. — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §4.3.3 p.37), printed p.13) [VC]', verified_at=now() where id='61702d9a-94f7-4a10-96d2-4afd2ab9065c' and verification_status not in ('verified_against_standard','corrected');
-- M816-09.p_wbzw_percent
update public.fields set verification_status='verified_against_standard', verification_quote='Dazu wird hier von einer Wiederbeschaffungszeitwert (WBZW-)Abschreibung mit einer Preissteigerung von $p=1 \%$ und von kalkulatorischen Zinsen mit einem kalkulatorischen Zinssatz $Z_{\mathrm{K}}=6 \%$ und einem Abzugskapitalanteil von $a=30 \%$ ausgegangen. | Weiterhin kann abhängig vom KAG gegebenenfalls statt der üblichen Abschreibung auf Anschaffungs- und Herstellungskosten eine Wiederbeschaffungszeitwert-Abschreibung angesetzt werden. — printed p.44', verification_note='md-verified 2026-09-05 (§4.7 (second fragment §5.3.8.1 p.72), printed p.44) [VC]', verified_at=now() where id='ddffc549-afcc-4a17-9e95-fec393f1195f' and verification_status not in ('verified_against_standard','corrected');

