-- M816-10.interest_rate
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $q$ & - & Abzinsungszinsfaktor für die Barwertermittlung $q=1+i$ \\ | Für die weiteren Berechnungen in diesem Abschnitt wird zunächst vereinfachend ein einheitlicher Abzinsungszinssatz $i=3 \%$ bzw. Abzinsungsfaktor $q=i+1=1,03$ vorgegeben. — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §4.1.1 p.21), printed p.13) [VC]', verified_at=now() where id='ef0a199b-acf9-42b8-b0e9-c90483573082' and verification_status not in ('verified_against_standard','corrected');
