-- ---- M816-11 ARBF — Rekursive Formeln ----
-- M816-11.rbf_0
update public.fields set verification_status='verified_against_standard', verification_quote='Mittels des klassischen Rentenbarwertfaktors RBF( $n, q$ ) kann der Gegenwarts- oder Barwert einer regelmäßig wiederholten gleichbleibenden Zahlung, etwa einer Rente, direkt formelmäßig für eine vorgegebene Anzahl $n$ von Zahlungen und einen vorgegebenen Abzinsungssatz $i$ bzw. Abzinsungsfaktor $q$ ermittelt werden: | \operatorname{RBF}_{0}(n ; q)=\left(1-1 / q^{n}\right) /(q-1) \quad q \neq 1 \tag{A.1} — printed p.100', verification_note='md-verified 2026-09-05 (Anhang A.1, Gl. (A.1), printed p.100) [VC]', verified_at=now() where id='6701639a-56f1-4184-837e-396cab8bf21f' and verification_status not in ('verified_against_standard','corrected');
-- M816-11.rbf_k
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $\mathrm{RBF}_{k}(n ; q)$ & - & Allgemeiner Rentenbarwertfaktor des Grades $k$ für die Barwertermittlung, der gemäß der für den jeweiligen Grad $k$ geltenden Formel in Anhang A durch $n$ und $q$ bestimmt wird \\ | Das neue Instrument hat erhebliche rechentechnische Vorteile, da sich jeder Allgemeine Rentenbarwertfaktor - wie das nachstehende Berechnungsschema zeigt - rekursiv über seine Vorgänger berechnen lässt. — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment Anhang A.1 p.100), printed p.13) [VC]', verified_at=now() where id='4c5985e4-1bd4-4841-9405-097a80ce95e2' and verification_status not in ('verified_against_standard','corrected');
-- M816-11.rbf_inflation_arg
update public.fields set verification_status='verified_against_standard', verification_quote='Er kann um einen weiteren Parameter, nämlich um den Preisindex $p$ zu $\mathrm{RBF}_{k}(n ; q / p)$ erweitert werden, und somit direkt für die Bewertung auch inflationsabhängiger Zahlungsprozesse verwendet werden. — printed p.100', verification_note='md-verified 2026-09-05 (Anhang A.1, printed p.100) [VC]', verified_at=now() where id='0c6ff4dc-4fa7-4e20-b6ec-011bbb176b55' and verification_status not in ('verified_against_standard','corrected');
-- M816-11.RBF_0
update public.fields set verification_status='verified_against_standard', verification_quote='\operatorname{RBF}_{0}(n ; q)=\left(1-1 / q^{n}\right) /(q-1) \quad q \neq 1 \tag{A.1} | & \operatorname{RBF}_{0}(n ; q)=\left(1-1 / q^{n}\right) /(q-1) \\ — printed p.100', verification_note='md-verified 2026-09-05 (Anhang A.1, Gl. (A.1) + Rekursionsschema, printed p.100) [VC]', verified_at=now() where id='90227f0b-35dc-4e58-bf7f-f6c86dd513e0' and verification_status not in ('verified_against_standard','corrected');
-- M816-11.q
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $q$ & - & Abzinsungszinsfaktor für die Barwertermittlung $q=1+i$ \\ | Die ARBF sind jeweils durch zwei Parameter, die Laufzeit $n$ und den Abzinsungszinssatz $i$ bzw. Abzinsungsfaktor $q=1+i$, bestimmt. — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §4.1.2 p.22), printed p.13) [VC]', verified_at=now() where id='b17a40e1-6ef0-4d79-96f5-1ac7077e8347' and verification_status not in ('verified_against_standard','corrected');
-- M816-11.n
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $n$ & Jahre & Anzahl der Jahre des Betrachtungszeitraums (Planungshorizonts) \\ | Die ARBF sind jeweils durch zwei Parameter, die Laufzeit $n$ und den Abzinsungszinssatz $i$ bzw. Abzinsungsfaktor $q=1+i$, bestimmt. — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §4.1.2 p.22), printed p.13) [VC]', verified_at=now() where id='0334abe1-4fd9-4648-b589-7f5ef24589ae' and verification_status not in ('verified_against_standard','corrected');
-- M816-11.RBF_1
update public.fields set verification_status='verified_against_standard', verification_quote='& \operatorname{RBF}_{1}(n ; q)=\left(\operatorname{RBF}_{0}(n ; q)+1-(n+1)^{1} / q^{n}\right) /(q-1) \\ — printed p.100', verification_note='md-verified 2026-09-05 (Anhang A.1 Rekursionsschema, printed p.100) [VC]', verified_at=now() where id='1fd9f153-e93f-4741-86fd-8123c492f84c' and verification_status not in ('verified_against_standard','corrected');
-- M816-11.RBF_2
update public.fields set verification_status='verified_against_standard', verification_quote='& \operatorname{RBF}_{2}(n ; q)=\left(\operatorname{RBF}_{0}(n ; q)+2 \operatorname{RBF}_{1}(n ; q)+1-(n+1)^{2} / q^{n}\right) /(q-1) \\ — printed p.100', verification_note='md-verified 2026-09-05 (Anhang A.1 Rekursionsschema, printed p.100) [VC]', verified_at=now() where id='bb5bbd77-9c35-472a-94e1-213e3283f189' and verification_status not in ('verified_against_standard','corrected');
-- M816-11.RBF_3
update public.fields set verification_status='verified_against_standard', verification_quote='& \operatorname{RBF}_{3}(n ; q)=\left(\operatorname{RBF}_{0}(n ; q)+3 \operatorname{RBF}_{1}(n ; q)+3 \operatorname{RBF}_{2}(n ; q)+1-(n+1)^{3} / q^{n}\right) /(q-1) \\ — printed p.100', verification_note='md-verified 2026-09-05 (Anhang A.1 Rekursionsschema, printed p.100) [VC]', verified_at=now() where id='3f96bd32-b7c1-4133-8ba4-8754d93390ec' and verification_status not in ('verified_against_standard','corrected');
-- M816-11.RBF_4
update public.fields set verification_status='verified_against_standard', verification_quote='& \operatorname{RBF}_{4}(n ; q)=\left(\operatorname{RBF}_{0}(n ; q)+4 \operatorname{RBF}_{1}(n ; q)+6 \operatorname{RBF}_{2}(n ; q)+4 \operatorname{RBF}_{3}(n ; q)+1-(n+1)^{4} / q^{n}\right) /(q-1) \\ — printed p.100', verification_note='md-verified 2026-09-05 (Anhang A.1 Rekursionsschema, printed p.100) [VC]', verified_at=now() where id='e558948a-0ef0-4994-b63b-9104043b7c25' and verification_status not in ('verified_against_standard','corrected');
-- M816-11.RBF_5
update public.fields set verification_status='verified_against_standard', verification_quote='& \operatorname{RBF}_{5}(n ; q)=\left(\operatorname{RBF}_{0}(n ; q)+5 \operatorname{RBF}_{1}(n ; q)+10 \operatorname{RBF}_{2}(n ; q)+10 \operatorname{RBF}_{3}(n ; q)+5 \operatorname{RBF}_{4}(n ; q)+1-(n+1)^{5} / q^{n}\right) /(q-1) — printed p.100', verification_note='md-verified 2026-09-05 (Anhang A.1 Rekursionsschema, printed p.100) [VC]', verified_at=now() where id='aad391cd-07ee-4246-b00b-daf7a2d56faa' and verification_status not in ('verified_against_standard','corrected');

-- ---- M816-12 Konstante Zahlungsprozesse ----
-- M816-12.c_0
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $c_{\mathrm{k}}$ & - & Koeffizienten des Zeitterms $t^{\mathrm{k}} ; k=0,1,2, \ldots, \mathrm{~m}$. Sie bestimmen die Form der Zahlungsfunktion $Z(t)$. \\ | Konstante Zahlungsprozesse werden durch konstante Zahlungsfunktionen abgebildet. Diese weisen einen in jeder Periode gleichhohen Zahlungsbetrag $c_{0}$ auf. In Bezug auf die Zeitabhängigkeit liegt hier ein vom Zeitindex $t$ unbeeinflusster Zahlungsprozess vom Grade 0 (erkennbar am Zeitterm $t^{0}=1$ ) vor: — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §4.1.2 p.22), printed p.13) [VC]', verified_at=now() where id='b97a50ab-27bc-422a-a832-b6a708e7cafc' and verification_status not in ('verified_against_standard','corrected');
-- M816-12.z_t
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $Z(t)$ & Währung & Zeitabhängige Zahlungsfunktion über alle Jahre $t=1, \ldots, n$ für den Zahlungsprozess einer bestimmten Kostengröße \\ | Z(t)=c_{0} \cdot t^{0}\left(=c_{0}\right) \quad t=1, \ldots, n \tag{1a} — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment Gl. 1a, §4.1.2 p.22), printed p.13) [VC]', verified_at=now() where id='10b21ebd-876a-4eb2-a59a-21c1b266bd2e' and verification_status not in ('verified_against_standard','corrected');
-- M816-12.bw
update public.fields set verification_status='verified_against_standard', verification_quote='\hline BW & Währung & Barwert = Summe der abgezinsten Zahlungen eines Zahlungsprozesses im Betrachtungszeitraum (in der Formelnummerierung durch .,a" gekennzeichnet) \\ | \mathrm{BW}=c_{0} \cdot \mathrm{RBF}_{0}(n ; q) \tag{1b} — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment Gl. 1b, §4.1.2 p.22), printed p.13) [VC]', verified_at=now() where id='b0071d8f-02bd-4e62-b8b5-0f1add536fa2' and verification_status not in ('verified_against_standard','corrected');
-- M816-12.Z
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $Z(t)$ & Währung & Zeitabhängige Zahlungsfunktion über alle Jahre $t=1, \ldots, n$ für den Zahlungsprozess einer bestimmten Kostengröße \\ | Z(t)=c_{0} \cdot t^{0}\left(=c_{0}\right) \quad t=1, \ldots, n \tag{1a} — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment Gl. 1a, §4.1.2 p.22), printed p.13) [VC]', verified_at=now() where id='78669c4c-dcbe-4b5f-aacd-fc8ec2a75cf1' and verification_status not in ('verified_against_standard','corrected');
-- M816-12.t
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $t$ & Jahr & Zeitindex für ein bestimmtes Jahr \\ | Z(t)=c_{0} \cdot t^{0}\left(=c_{0}\right) \quad t=1, \ldots, n \tag{1a} — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment Gl. 1a, §4.1.2 p.22), printed p.13) [VC]', verified_at=now() where id='ae05ec1a-b560-4881-a59c-35727ba60769' and verification_status not in ('verified_against_standard','corrected');
-- M816-12.n
