-- ---- M816-13 Lineare Zahlungsprozesse ----
-- M816-13.c_1
update public.fields set verification_status='verified_against_standard', verification_quote='Lineare Zahlungsfunktionen weisen zusätzlich eine mit dem Zeitindex $t$ um einen Zahlungsbetrag $c_{1}$ anwachsende oder schrumpfende Zahlungskomponente auf. Damit liegt bezogen auf die Zeitabhängigkeit ein vom Zeitindex $t$ linear beeinflusster Zahlungsprozess vom Grade $1\left(t^{1}\right)$ vor: | Z(t)=c_{0} \cdot t^{0}+c_{1} \cdot t^{1}\left(=c_{0}+c_{1} \cdot t\right) \quad t=1, \ldots, n \tag{2a} — printed p.23', verification_note='md-verified 2026-09-05 (§4.1.3, Gl. (2a), printed p.23) [VC]', verified_at=now() where id='727a8eb7-aef0-4b7c-8ebb-cc3187cef300' and verification_status not in ('verified_against_standard','corrected');
-- M816-13.c_0_lin
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $c_{\mathrm{k}}$ & - & Koeffizienten des Zeitterms $t^{\mathrm{k}} ; k=0,1,2, \ldots, \mathrm{~m}$. Sie bestimmen die Form der Zahlungsfunktion $Z(t)$. \\ | Z(t)=c_{0} \cdot t^{0}+c_{1} \cdot t^{1}\left(=c_{0}+c_{1} \cdot t\right) \quad t=1, \ldots, n \tag{2a} — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment Gl. 2a, §4.1.3 p.23), printed p.13) [VC]', verified_at=now() where id='fe57665c-5eef-42e0-a8c5-4082f4ca4759' and verification_status not in ('verified_against_standard','corrected');
-- M816-13.Z_t_linear
update public.fields set verification_status='verified_against_standard', verification_quote='Lineare Zahlungsfunktionen weisen zusätzlich eine mit dem Zeitindex $t$ um einen Zahlungsbetrag $c_{1}$ anwachsende oder schrumpfende Zahlungskomponente auf. Damit liegt bezogen auf die Zeitabhängigkeit ein vom Zeitindex $t$ linear beeinflusster Zahlungsprozess vom Grade $1\left(t^{1}\right)$ vor: | Z(t)=c_{0} \cdot t^{0}+c_{1} \cdot t^{1}\left(=c_{0}+c_{1} \cdot t\right) \quad t=1, \ldots, n \tag{2a} — printed p.23', verification_note='md-verified 2026-09-05 (§4.1.3, Gl. (2a), printed p.23) [VC]', verified_at=now() where id='40273312-8c01-4490-ac6d-a84750351781' and verification_status not in ('verified_against_standard','corrected');
-- M816-13.BW_linear
update public.fields set verification_status='verified_against_standard', verification_quote='Denn durch schematische Ersetzung der beiden Zeitterme $t^{0}$ und $t^{1}$ in Gleichung (2a) durch die gradgleichen ARBF erhält man direkt den Barwert dieser linearen Zahlungsfunktion: | \mathrm{BW}=c_{0} \cdot \mathrm{RBF}_{0}(n ; q)+c_{1} \cdot \mathrm{RBF}_{1}(n ; q) \tag{2b} — printed p.23', verification_note='md-verified 2026-09-05 (§4.1.3, Gl. (2b), printed p.23) [VC]', verified_at=now() where id='49d973ec-3c0b-480d-8e24-c094a01e756e' and verification_status not in ('verified_against_standard','corrected');
