-- ---- M816-14 Quadratische Zahlungsprozesse ----
-- M816-14.c_2
update public.fields set verification_status='verified_against_standard', verification_quote='Quadratische Zahlungsfunktionen weisen zusätzlich einen zeitabhängigen Term auf, der quadratisch mit der Zeit wächst oder schrumpft. Anwendungsfälle sind nach unten oder nach oben gewölbte (parabelförmige) Zahlungsverläufe, die typischerweise bei Instandhaltungsausgaben bzw. bei Umsätzen im Rahmen eines Produktlebenszyklus anzutreffen sind. | Z(t)=c_{0} \cdot t^{0}+c_{1} \cdot t^{1}+c_{2} \cdot t^{2} & t=1, \ldots, n \\ \mathrm{BW}=c_{0} \cdot \mathrm{RBF}_{0}(n ; q)+c_{1} \cdot \mathrm{RBF}_{1}(n ; q)+c_{2} \cdot \mathrm{RBF}_{2}(n ; q) — printed p.25', verification_note='md-verified 2026-09-05 (§4.1.4, printed p.25) [VC]', verified_at=now() where id='e0953dcc-592e-4958-aaf6-a12815bb6548' and verification_status not in ('verified_against_standard','corrected');
