-- M816-15.c_k
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $c_{\mathrm{k}}$ & - & Koeffizienten des Zeitterms $t^{\mathrm{k}} ; k=0,1,2, \ldots, \mathrm{~m}$. Sie bestimmen die Form der Zahlungsfunktion $Z(t)$. \\ | Die Koeffizienten $c_{0}$ bis $c_{\mathrm{m}}$ solcher Zeitpolynome lassen sich über numerische Verfahren zur Erzeugung von Approximationsfunktionen, z. B. mittels der Methode der sog. „Dividierten Differenzen“ nach Neville/Aitkens, bestimmen. — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §4.1.5 p.27), printed p.13) [VC]', verified_at=now() where id='1bade021-740a-47e3-b41d-26a9219ee575' and verification_status not in ('verified_against_standard','corrected');
-- M816-15.Z
update public.fields set verification_status='verified_against_standard', verification_quote='Zahlungsfunktion und Barwert für den allgemeinen Zahlungsprozess unter Verwendung des Summationszeichens $\sum$ für eine Summation über alle relevanten Grade $k=0,1,2, \ldots, m$ des Zahlungsprozesses lauten: | Z(t) & =c_{0} \cdot t^{0}+c_{1} \cdot t^{1}+c_{2} \cdot t^{2}+\ldots+c_{m} \cdot t^{m} \tag{4a}\\ & =\sum c_{k} \cdot t^{k} \quad t=1, \ldots, n — printed p.27', verification_note='md-verified 2026-09-05 (§4.1.5, Gl. (4a), printed p.27) [VC]', verified_at=now() where id='d09269a7-b87f-431d-bb77-a268b1e79011' and verification_status not in ('verified_against_standard','corrected');
