-- M816-16.Z_t_inflation
update public.fields set verification_status='verified_against_standard', verification_quote='Formal erfolgt die Preisindexierung der einzelnen Zahlungsprozesse $Z(t)$ mittels der jeweiligen spezifischen, nominalen Preissteigerungsrate $p \%$, um dann ausgehend von der Formulierung in GI. (4a) explizit Zahlungsfunktionen mit Inflationsberücksichtigung zu erhalten: | Z(t)=\sum c_{k} \cdot t^{k} \cdot p^{t} \tag{5a} \end{equation*} $$ $$ t=1, \ldots, n \text { mit } p=1+p \% — printed p.28', verification_note='md-verified 2026-09-05 (§4.1.6, Gl. (5a), printed p.28) [VC]', verified_at=now() where id='3a773012-6497-4323-a47e-eb745066e2fa' and verification_status not in ('verified_against_standard','corrected');
-- M816-16.BW_inflation
update public.fields set verification_status='verified_against_standard', verification_quote='Die Ausmultiplizierung der Zeitterme $t^{k}$ mit dem Preisindex $p^{\dagger}$ ermöglicht sofort die Substitution der einzelnen, nun zusätzlich inflationsbeeinflussten Zeitterme $t^{k} p^{t}$ durch entsprechende Inflation berücksichtigende $\mathrm{ARBF} \mathrm{RBF}_{\mathrm{k}}(n ; q / p)$ für die Barwertermittlung: | \mathrm{BW}=\sum c_{\mathrm{k}} \cdot \mathrm{RBF}_{\mathrm{k}}(n ; q / p) \tag{5b} — printed p.28', verification_note='md-verified 2026-09-05 (§4.1.6, Gl. (5b), printed p.28) [VC]', verified_at=now() where id='8e75a36f-4e96-4501-98cd-af533b4d3c66' and verification_status not in ('verified_against_standard','corrected');
-- M816-16.q_DUR
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $q_{\text {DUR }}$ & - & Abzinsungsfaktor $q_{\text {DUR }}=i_{\text {DUR }}+1$ für eine durationsentsprechende Barwertermittlung \\ | Mit Gl. (5c) ist es jetzt möglich, den zu wählenden Abzinsungssatz $i$ bzw. Abzinsungsfaktor $q$ exakt auf die jeweilige individuelle mittlere Zahlungsfälligkeit des Zahlungsprozesses abzustimmen, um so die durationsentsprechende Abzinsung mit $i_{\text {DUR }}$ zu erhalten - und damit auch einen den genaueren durationsentsprechenden Abzinsungsfaktor: — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §4.2.2 p.33), printed p.13) [VC]', verified_at=now() where id='efc98c13-a82c-4927-a3f1-7254539cab7d' and verification_status not in ('verified_against_standard','corrected');
