-- M816-17.bw_1
update public.fields set verification_status='verified_against_standard', verification_quote='& \mathrm{BW}=\mathrm{BW}_{1}+1 / q^{\mathrm{n} 1} \cdot \mathrm{BW}_{2} \tag{6b} | Der Barwert des zweiten Teils weist einen Vorlauf von $n_{1}$ Jahren auf (siehe dazu auch 4.3) und muss daher um diesen Zeitraum abgezinst werden. — printed p.29', verification_note='md-verified 2026-09-05 (§4.1.7, Gl. (6b), printed p.29) [VC]', verified_at=now() where id='eb768dae-0b54-4e30-81f7-6cb078f73f66' and verification_status not in ('verified_against_standard','corrected');
