-- M816-17.Z
update public.fields set verification_status='verified_against_standard', verification_quote='Über zusammengesetzte Zahlungsprozesse kann ein Wechsel der Funktionalität im Zeitablauf dargestellt werden. So ist zum Beispiel ein linearer Abbauprozess nach $n_{1}$ Jahren beendet und geht danach für die anschließenden $n_{2}$ Jahre in einen stabilen konstanten Prozess über. Die entsprechenden Zusammenhänge für die aus zwei Teilen bestehende Zahlungsfunktion und den Barwert lassen sich allgemein folgendermaßen angeben: | & Z(t): Z_{1}(t) \text { mit } t=1, \ldots, n_{1} \text { und nachfolgend } Z_{2}(t) \text { mit } t=n_{1}+1, \ldots, n_{1}+n_{2} \tag{6a}\\ — printed p.29', verification_note='md-verified 2026-09-05 (§4.1.7, Gl. (6a), printed p.29) [VC]', verified_at=now() where id='44777c4e-952e-467a-a816-37eab5f5d273' and verification_status not in ('verified_against_standard','corrected');
