-- ---- M816-18 Koeffizienten-Zusammenfassung ----
-- M816-18.payment_process_count
update public.fields set verification_status='verified_against_standard', verification_quote='Das Projektergebnis einer Alternative ergibt sich aus der Zusammenfassung sämtlicher für die Alternative definierten Zahlungsprozesse. Mit der EXCEL-Berechnungshilfe in Anhang B lassen sich sofort die in EXCEL zeilenweise abgebildeten und bewerteten Zahlungsprozesse in einer Gesamttabelle zusammenfassen. | Die Berechnungshilfe besteht letztlich aus einer einzigen standardisierten EXCEL-Zeile, die beliebig oft für weitere Zahlungsprozesse kopiert werden kann. — printed p.44', verification_note='md-verified 2026-09-05 (§4.7 (second fragment Anhang B p.102), printed p.44) [VC]', verified_at=now() where id='282323c7-3e59-4b2d-959f-0457d4632d7a' and verification_status not in ('verified_against_standard','corrected');
-- M816-18.coefficient_set_used
update public.fields set verification_status='verified_against_standard', verification_quote='Nach der Kopie sind für den neuen Zahlungsprozess zunächst die Parameter und dann die aus diesen abgeleiteten Zahlungskoeffizienten $c_{k}$ einzugeben. | \hline $c_{\mathrm{k}}$ & - & Koeffizienten des Zeitterms $t^{\mathrm{k}} ; k=0,1,2, \ldots, \mathrm{~m}$. Sie bestimmen die Form der Zahlungsfunktion $Z(t)$. \\ — printed p.102', verification_note='md-verified 2026-09-05 (Anhang B (second fragment §2 Formelzeichen p.13), printed p.102) [VC]', verified_at=now() where id='eec88d64-1068-4d1c-bfdc-59eec3e7e8b2' and verification_status not in ('verified_against_standard','corrected');
-- M816-18.highest_order_polynomial
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $m$ & - & Maximaler Grad (Exponent) einer Zahlungsfunktion $Z(t)$ \\ | Generell lassen sich aber bereits zum Beispiel über Zeitpolynome des 4. Grades ( $m=4$ ), also mit 5 Zahlungskoeffizienten $c_{0}$ bis $c_{4}$ als „Stellschrauben“, Zahlungsfunktionen so „hinbiegen“, dass nahezu jeder in der Praxis bekannte nicht lineare Zahlungsverlauf einer relevanten Kostengröße zutreffend approximiert werden kann. — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §4.1.5 p.27), printed p.13) [VC]', verified_at=now() where id='acb6b61b-6cf8-4c34-b6d9-a131349131ba' and verification_status not in ('verified_against_standard','corrected');

-- ---- M816-19 Durationsberechnung ----
-- M816-19.duration
update public.fields set verification_status='verified_against_standard', verification_quote='\hline DUR & Jahre & Duration = Mittlere (barwertgewichtete) Zahlungsdauer eines Zahlungsprozesses (in der Formelnummerierung durch „b“ gekennzeichnet) \\ | Vereinfachend wird daher einheitlich der Zinssatz $i_{\text {DUR }}$ für die durchschnittliche Fälligkeit des jeweiligen Zahlungsprozesses zugrunde gelegt, die als sogenannte Duration DUR als mittlere (barwertgewichtete) Zahlungsdauer eines Zahlungsprozesses ermittelt wird. Bei einer Duration einer Kostengröße von zum Beispiel 15 Jahren wäre danach gemäß Bild 7 ein durationskongruenter Bundesbank-Abzinsungssatz von $i_{\text {DUR }}=3,68 \%$ anzuwenden. — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §4.2.2 p.33), printed p.13) [VC]', verified_at=now() where id='01f08146-2459-46ac-b7f1-7b1ca70f9abe' and verification_status not in ('verified_against_standard','corrected');
-- M816-19.duration_method
update public.fields set verification_status='verified_against_standard', verification_quote='Die Duration DUR ergibt sich als Verhältnis von Summenprodukten aus Koeffizienten und ARBF, wobei im Zähler um einen Grad höhere Rentenbarwertfaktoren $\operatorname{RBF}_{\mathrm{k}+1}(n ; q / p), k+1=1, \ldots, m+1$ zu verwenden sind. ${ }^{11]}$ Dabei ist $q$ zunächst mit einem plausiblen Startwert, z. B. 1,03 zu belegen: | \mathrm{DUR}=\sum c_{\mathrm{k}} \cdot \mathrm{RBF}_{\mathrm{k}+1}(n ; q / p) / \sum c_{\mathrm{k}} \cdot \mathrm{RBF}_{\mathrm{k}}(n ; q / p) \tag{5c} — printed p.33', verification_note='md-verified 2026-09-05 (§4.2.2, Gl. (5c), printed p.33) [VC] — caveat: the guideline gives exactly ONE duration method (Gl. 5c); the free-text selector is EKOWAI’s wrapper', verified_at=now() where id='0cc69a34-a114-45b4-975b-2e7f10a6f5ac' and verification_status not in ('verified_against_standard','corrected');
-- M816-19.duration_years
update public.fields set verification_status='verified_against_standard', verification_quote='\hline DUR & Jahre & Duration = Mittlere (barwertgewichtete) Zahlungsdauer eines Zahlungsprozesses (in der Formelnummerierung durch „b“ gekennzeichnet) \\ | Vereinfachend wird daher einheitlich der Zinssatz $i_{\text {DUR }}$ für die durchschnittliche Fälligkeit des jeweiligen Zahlungsprozesses zugrunde gelegt, die als sogenannte Duration DUR als mittlere (barwertgewichtete) Zahlungsdauer eines Zahlungsprozesses ermittelt wird. Bei einer Duration einer Kostengröße von zum Beispiel 15 Jahren wäre danach gemäß Bild 7 ein durationskongruenter Bundesbank-Abzinsungssatz von $i_{\text {DUR }}=3,68 \%$ anzuwenden. — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §4.2.2 p.33), printed p.13) [VC]', verified_at=now() where id='a7481b86-2465-4ed0-b45b-bf4ecb0825f7' and verification_status not in ('verified_against_standard','corrected');
