-- M816-19.n
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $n$ & Jahre & Anzahl der Jahre des Betrachtungszeitraums (Planungshorizonts) \\ | \mathrm{DUR}=\sum c_{\mathrm{k}} \cdot \mathrm{RBF}_{\mathrm{k}+1}(n ; q / p) / \sum c_{\mathrm{k}} \cdot \mathrm{RBF}_{\mathrm{k}}(n ; q / p) \tag{5c} — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment Gl. 5c, §4.2.2 p.33), printed p.13) [VC]', verified_at=now() where id='9ef2851b-7bdb-4a65-80df-a8c304c2cab2' and verification_status not in ('verified_against_standard','corrected');
-- M816-19.RBF_k
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $\mathrm{RBF}_{k}(n ; q)$ & - & Allgemeiner Rentenbarwertfaktor des Grades $k$ für die Barwertermittlung, der gemäß der für den jeweiligen Grad $k$ geltenden Formel in Anhang A durch $n$ und $q$ bestimmt wird \\ | \mathrm{DUR}=\sum c_{\mathrm{k}} \cdot \mathrm{RBF}_{\mathrm{k}+1}(n ; q / p) / \sum c_{\mathrm{k}} \cdot \mathrm{RBF}_{\mathrm{k}}(n ; q / p) \tag{5c} — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment Gl. 5c, §4.2.2 p.33), printed p.13) [VC]', verified_at=now() where id='11a0ab3b-38eb-458e-9d30-6138db780191' and verification_status not in ('verified_against_standard','corrected');

-- ---- M816-20 Durationsabhängige Abzinsung ----
-- M816-20.i_dur
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $i_{\text {DUR }}$ & \% p. a. & Abzinsungszinssatz der Deutschen Bundesbank für eine durationsentsprechende Barwertermittlung pro Jahr \\ | Vereinfachend wird daher einheitlich der Zinssatz $i_{\text {DUR }}$ für die durchschnittliche Fälligkeit des jeweiligen Zahlungsprozesses zugrunde gelegt, die als sogenannte Duration DUR als mittlere (barwertgewichtete) Zahlungsdauer eines Zahlungsprozesses ermittelt wird. Bei einer Duration einer Kostengröße von zum Beispiel 15 Jahren wäre danach gemäß Bild 7 ein durationskongruenter Bundesbank-Abzinsungssatz von $i_{\text {DUR }}=3,68 \%$ anzuwenden. — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §4.2.2 p.33), printed p.13) [VC]', verified_at=now() where id='320eae47-7f24-4926-b34c-2395ebc76f36' and verification_status not in ('verified_against_standard','corrected');
-- M816-20.q_dur
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $q_{\text {DUR }}$ & - & Abzinsungsfaktor $q_{\text {DUR }}=i_{\text {DUR }}+1$ für eine durationsentsprechende Barwertermittlung \\ | Mit Gl. (5c) ist es jetzt möglich, den zu wählenden Abzinsungssatz $i$ bzw. Abzinsungsfaktor $q$ exakt auf die jeweilige individuelle mittlere Zahlungsfälligkeit des Zahlungsprozesses abzustimmen, um so die durationsentsprechende Abzinsung mit $i_{\text {DUR }}$ zu erhalten - und damit auch einen den genaueren durationsentsprechenden Abzinsungsfaktor: — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §4.2.2 p.33), printed p.13) [VC]', verified_at=now() where id='126cabb9-30f1-4c9d-8b06-8706003a95f7' and verification_status not in ('verified_against_standard','corrected');

-- ---- M816-21 Besondere Zahlungsmerkmale ----
-- M816-21.vorlauf_v
update public.fields set verification_status='verified_against_standard', verification_quote='\hline v & Jahre & Vorlaufjahre bis zu einer Reinvestition \\ | Regelmäßig liegen Zahlungsvorläufe bei Reinvestitionen von Anlagekomponenten vor. So muss nach dem Nutzungsende einer Anlagenkomponente, zum Beispiel nach 20 Jahren, eine Reinvestition erfolgen und finanziert werden. Bei Zahlungsprozessen mit Vorlauf muss in vielen Fällen auch die Inflation innerhalb der Vorlaufphase berücksichtigt werden. Der Barwert des Zahlungsprozesses muss also entsprechend der Jahresanzahl der Vorlaufphase inflationiert und abgezinst werden. — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §4.3.3 p.37), printed p.13) [VC]', verified_at=now() where id='28285c78-c8e7-41ff-a6d4-dca9d77aaf3b' and verification_status not in ('verified_against_standard','corrected');
-- M816-21.payment_takt_u
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $u$ & - & Zahltakt, z. B. $u=1$ jedes Jahr, $u=2$ alle zwei Jahre \\ | Ein nützliches Feature der in Anhang B dokumentierten EXCEL-Berechnungshilfe für eine realistische Abbildung von Zahlungsvorgängen ist die Möglichkeit, in der Spalte „Takt“ festzulegen, dass nicht jedes Jahr ( $u=1$ ), sondern beispielsweise nur alle $2(u=2)$ wie in Bild 8 dargestellt oder alle $5(u=5)$ Jahre eine Zahlung erfolgt. — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §4.3.1 p.36), printed p.13) [VC]', verified_at=now() where id='73646ffa-30fd-47a4-8a1c-6e8c3d4d9e2b' and verification_status not in ('verified_against_standard','corrected');

-- ---- M816-22 Teilreplikation ----
-- M816-22.n_tr
update public.fields set verification_status='verified_against_standard', verification_quote='Bei teilreplizierten Finanzierungszahlungsprozessen ist die Besonderheit zu berücksichtigen, dass die Finanzierungsdauer $n_{\text {Fin }}$ regelmäßig kürzer als die Nutzungsdauern der finanzierten Investitionen ist. Daher ist die Nutzungsdauerdifferenz in den obigen Gln. (6a) bis (6c) durch eine mit dem Faktor $n_{\text {Fin }} / n_{\mathrm{B}}$ proportionalisierte Laufzeit $n_{\text {TR }}$ zu ersetzen: | n_{T R}=\left(n_{A}-n_{B}\right) \cdot n_{\text {Fin }} / n_{B} \tag{7} — printed p.39', verification_note='md-verified 2026-09-05 (§4.4.2, Gl. (7), printed p.39) [VC]', verified_at=now() where id='9c7476bf-ee9b-49d7-885a-4767a036fe2d' and verification_status not in ('verified_against_standard','corrected');
-- M816-22.dur_tr
update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Ermittlung der Duration muss nun zusätzlich der Vorlauf von $n_{\mathrm{B}}$ Jahren der kürzeren Alternative berücksichtigt werden, sodass folgt: | \mathrm{DUR}_{\mathrm{TR}}=n_{\mathrm{B}}+\sum c_{\mathrm{k}} \cdot \mathrm{RBF}_{\mathrm{k}+1} \cdot\left(n_{\mathrm{A}}-n_{\mathrm{B}} ; q / p\right) / \sum c_{\mathrm{k}} \cdot \mathrm{RBF}_{\mathrm{k}}\left(n_{\mathrm{A}}-n_{\mathrm{B}} ; q / p\right) \tag{6c} — printed p.39', verification_note='md-verified 2026-09-05 (§4.4.2, Gl. (6c), printed p.39) [VC]', verified_at=now() where id='40e14ce2-60dd-44c9-b083-d123bbdd9d18' and verification_status not in ('verified_against_standard','corrected');
-- M816-22.bw_tr
update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Teilreplikation wird die kürzere Alternative (B) entsprechend der Nutzungsdauerdifferenz zwischen langer und kurzer Alternative teilweise repliziert. Die zusätzlich benötigten Zahlungsprozesse der Teilreplikation der kürzeren Alternative lassen sich allgemein formulieren als: | & \mathrm{BW}_{T R}=\left(p_{v} / q\right)^{\mathrm{nB}} \cdot \sum c_{k} \cdot \mathrm{RBF}_{k}\left(n_{A}-n_{B} ; q / p\right) \tag{6b} — printed p.39', verification_note='md-verified 2026-09-05 (§4.4.2, Gl. (6b), printed p.39) [VC]', verified_at=now() where id='5c123748-98bd-4a61-81f7-8fd5a387efc6' and verification_status not in ('verified_against_standard','corrected');
-- M816-22.DUR_TR
update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Ermittlung der Duration muss nun zusätzlich der Vorlauf von $n_{\mathrm{B}}$ Jahren der kürzeren Alternative berücksichtigt werden, sodass folgt: | \mathrm{DUR}_{\mathrm{TR}}=n_{\mathrm{B}}+\sum c_{\mathrm{k}} \cdot \mathrm{RBF}_{\mathrm{k}+1} \cdot\left(n_{\mathrm{A}}-n_{\mathrm{B}} ; q / p\right) / \sum c_{\mathrm{k}} \cdot \mathrm{RBF}_{\mathrm{k}}\left(n_{\mathrm{A}}-n_{\mathrm{B}} ; q / p\right) \tag{6c} — printed p.39', verification_note='md-verified 2026-09-05 (§4.4.2, Gl. (6c), printed p.39) [VC]', verified_at=now() where id='c9e201b5-d70a-4a1c-909d-9abfb1494939' and verification_status not in ('verified_against_standard','corrected');
-- M816-22.n_A
update public.fields set verification_status='verified_against_standard', verification_quote='In der Praxis stellt sich häufig das Problem, dass aufgrund unterschiedlicher Nutzungsdauern der Investitionen, also zum Beispiel $n_{\mathrm{A}}=30$ Jahre $>n_{\mathrm{B}}=25$ Jahre, die zu vergleichenden Alternativen zunächst unterschiedliche Betrachtungszeiträume aufweisen. | & Z_{T R}(t) ; t=1, \ldots, n_{A}-n_{B} \text { bei einem Vorlauf von } n_{B} \text { Jahren } \tag{6a}\\ — printed p.38', verification_note='md-verified 2026-09-05 (§4.4.1 (second fragment Gl. 6a, §4.4.2 p.39), printed p.38) [VC]', verified_at=now() where id='009a0c5a-1574-4ac0-8b0d-f615e1214a52' and verification_status not in ('verified_against_standard','corrected');
-- M816-22.n_B
update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Teilreplikation wird die kürzere Alternative (B) entsprechend der Nutzungsdauerdifferenz zwischen langer und kurzer Alternative teilweise repliziert. Die zusätzlich benötigten Zahlungsprozesse der Teilreplikation der kürzeren Alternative lassen sich allgemein formulieren als: | & Z_{T R}(t) ; t=1, \ldots, n_{A}-n_{B} \text { bei einem Vorlauf von } n_{B} \text { Jahren } \tag{6a}\\ — printed p.39', verification_note='md-verified 2026-09-05 (§4.4.2, Gl. (6a), printed p.39) [VC]', verified_at=now() where id='c245397e-0ea5-4171-a85d-155fbabebca6' and verification_status not in ('verified_against_standard','corrected');
-- M816-22.q
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $q$ & - & Abzinsungszinsfaktor für die Barwertermittlung $q=1+i$ \\ | & \mathrm{BW}_{T R}=\left(p_{v} / q\right)^{\mathrm{nB}} \cdot \sum c_{k} \cdot \mathrm{RBF}_{k}\left(n_{A}-n_{B} ; q / p\right) \tag{6b} — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment Gl. 6b, §4.4.2 p.39), printed p.13) [VC]', verified_at=now() where id='1abfdbae-a7a2-4a9d-a4b6-4c521cf52ec0' and verification_status not in ('verified_against_standard','corrected');
