update public.fields set verification_status='verified_against_standard', verification_quote='\hline $n_{\text {Fin }}$ & Jahre & Anzahl der Jahre des Finanzierungszeitraums \\ | n_{T R}=\left(n_{A}-n_{B}\right) \cdot n_{\text {Fin }} / n_{B} \tag{7} — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment Gl. 7, §4.4.2 p.39), printed p.13) [VC]', verified_at=now() where id='eb74451e-e1de-4c4a-8d8a-3cb528bcbc58' and verification_status not in ('verified_against_standard','corrected');
-- M816-22.Z_TR
