-- M816-22.BW_TR
update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Teilreplikation wird die kürzere Alternative (B) entsprechend der Nutzungsdauerdifferenz zwischen langer und kurzer Alternative teilweise repliziert. Die zusätzlich benötigten Zahlungsprozesse der Teilreplikation der kürzeren Alternative lassen sich allgemein formulieren als: | & \mathrm{BW}_{T R}=\left(p_{v} / q\right)^{\mathrm{nB}} \cdot \sum c_{k} \cdot \mathrm{RBF}_{k}\left(n_{A}-n_{B} ; q / p\right) \tag{6b} — printed p.39', verification_note='md-verified 2026-09-05 (§4.4.2, Gl. (6b), printed p.39) [VC]', verified_at=now() where id='9dd80618-5f7a-4e69-8430-95e2ceb68e07' and verification_status not in ('verified_against_standard','corrected');
