update public.fields set verification_status='verified_against_standard', verification_quote='\hline $p_{\mathrm{v}}$ & - & Inflationsfaktor $p_{\mathrm{v}}=p_{\mathrm{v}} \%+1$ in der Vorlaufphase bis zu einer Reinvestition \\ | & \mathrm{BW}_{T R}=\left(p_{v} / q\right)^{\mathrm{nB}} \cdot \sum c_{k} \cdot \mathrm{RBF}_{k}\left(n_{A}-n_{B} ; q / p\right) \tag{6b} — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment Gl. 6b, §4.4.2 p.39), printed p.13) [VC]', verified_at=now() where id='97d05c65-ad9a-432c-b034-84d2855c5ceb' and verification_status not in ('verified_against_standard','corrected');
