-- ---- M816-23 Gebührenrechnung ----
-- M816-23.kalk_zinssatz_zk
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $z_{\text {K }}$ & \% p. a. & Kalkulatorischer Zinssatz in der Gebührenrechnung pro Jahr \\ | Gebührenrechtlich kann gemäß 4.5.3 statt der tatsächlichen Verzinsung (hier 1,5 \%) eine kalkulatorische Verzinsung derzeit bis zu 7 \% nach vielen landesrechtlichen KAG angesetzt werden. — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §5.3.8.1 p.72), printed p.13) [VC] — caveat: the md gives an upper bound only ("bis zu 7 %", plus worked values zK = 6 % in §4.7 and 5 % in §5.3.8.1); no lower bound of 5 % is printed', verified_at=now() where id='6b9aa5f0-0e58-42a8-b507-da5a7f593940' and verification_status not in ('verified_against_standard','corrected');
-- M816-23.abzugskapital_a
update public.fields set verification_status='verified_against_standard', verification_quote='\hline a & \% & Prozentanteil des Abzugskapitals an den Anschaffungs- und Herstellungskosten \\ | Dieser Restbuchwert auf AHK-Basis ${ }^{18)}$ ist noch um das nicht durch die Kommune selbst finanzierte, sondern aus anderen Quellen (Zuschüsse, Beiträge) stammende sogenannte Abzugskapital ABK zu bereinigen, üblicherweise nach der sog. Prozentmethode als im Zeitablauf gleichbleibender Prozentanteil a des Abzugskapitals ABK an den ursprünglichen AHK ermittelt (BöttCHER 1998). Auf dieses verbleibende sogenannte Zinskapital ist dann der durch die Kommune festgelegte kalkulatorische Zinssatz $Z_{\mathrm{K}}$ anzuwenden. — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §4.5.3 p.40), printed p.13) [VC] — caveat: only one worked value is printed (a = 30 % in §4.7); the "typical 0,20-0,30" range in the field description is not in the source', verified_at=now() where id='0bca30b9-1acc-4f79-a723-e709234df17d' and verification_status not in ('verified_against_standard','corrected');
-- M816-23.afa
update public.fields set verification_status='verified_against_standard', verification_quote='\hline AFA & Währung & Jährliche Abschreibungsrate einer Investition \\ | Das kommunale Gebührenrecht in NRW - so in § 6 Abs. 2 KAG NRW - wie auch in einigen anderen Bundesländern - lässt als Grundlage für die Ermittlung der Gebühreneinnahmen aus kalkulatorischen Abschreibungen neben den Anschaffungs- und Herstellungskosten ( AHK ) auch die Wiederbeschaffungszeitwerte (WBZW) der Anlagegüter zu. Die Abschreibung AFA = AHK/n ist gleichmäßig nach der Nutzungsdauer $n$ zu bemessen (lineare Abschreibung). — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §4.5.3 p.40), printed p.13) [VC]', verified_at=now() where id='487d0245-9f2a-430c-b4d1-d9e63c55e76a' and verification_status not in ('verified_against_standard','corrected');
-- M816-23.rbw_t
update public.fields set verification_status='verified_against_standard', verification_quote='\hline RBW $_{\text {t }}$ & Währung & Restbuchwert einer Investition in einem bestimmten Jahr $t$ \\ | Im Allgemeinen wird dabei der Restbuchwert RBW ${ }_{\mathrm{t}-1}$ des Vorjahres $t-1$ zugrunde gelegt (alternativ könnte auch der mittlere Restbuchwert (RBW ${ }_{t-1}+\mathrm{RBW}_{t}$ ) / 2 verwendet werden), der sich bei Abschreibungen von jeweils AFA über $n$ Nutzungsjahren ergibt zu: | \mathrm{RBW}_{\mathrm{t}-1}=\mathrm{AFA} \cdot(n+1-\mathrm{t}) \tag{9} — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §4.5.3 p.40, Gl. 9), printed p.13) [VC]', verified_at=now() where id='8c752910-7c0d-416a-8285-b3775b9d70b4' and verification_status not in ('verified_against_standard','corrected');
-- M816-23.Z_AFA
update public.fields set verification_status='verified_against_standard', verification_quote='Auf vorstehenden Grundlagen lassen sich die Gebühreneinnahmen aus kalkulatorischen Abschreibungen durch folgende zeitkonstante Zahlungsfunktion mit Inflationsberücksichtigung $p^{\dagger}$ für eine Nutzungsdauer von $n$ Jahren inklusive Barwert beschreiben | \mathrm{Z}_{\mathrm{AFA}}(t)=\mathrm{AFA} \cdot p^{\mathrm{t}} \cdot t^{0} & t=1, \ldots, n \\ — printed p.40', verification_note='md-verified 2026-09-05 (§4.5.3, Gl. (8a), printed p.40) [VC]', verified_at=now() where id='fbe501b5-563b-4bfe-bf76-1b86cf326c00' and verification_status not in ('verified_against_standard','corrected');
-- M816-23.AFA
update public.fields set verification_status='verified_against_standard', verification_quote='\hline AFA & Währung & Jährliche Abschreibungsrate einer Investition \\ | Das kommunale Gebührenrecht in NRW - so in § 6 Abs. 2 KAG NRW - wie auch in einigen anderen Bundesländern - lässt als Grundlage für die Ermittlung der Gebühreneinnahmen aus kalkulatorischen Abschreibungen neben den Anschaffungs- und Herstellungskosten ( AHK ) auch die Wiederbeschaffungszeitwerte (WBZW) der Anlagegüter zu. Die Abschreibung AFA = AHK/n ist gleichmäßig nach der Nutzungsdauer $n$ zu bemessen (lineare Abschreibung). — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment §4.5.3 p.40), printed p.13) [VC]', verified_at=now() where id='d99ee410-5352-4bd4-beef-a0e59a66c1e1' and verification_status not in ('verified_against_standard','corrected');
-- M816-23.p
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $p$ & - & Inflationsfaktor $p=p \%+1$ einer Kostengröße \\ | \mathrm{Z}_{\mathrm{AFA}}(t)=\mathrm{AFA} \cdot p^{\mathrm{t}} \cdot t^{0} & t=1, \ldots, n \\ — printed p.13', verification_note='md-verified 2026-09-05 (§2 Formelzeichen (second fragment Gl. 8a, §4.5.3 p.40), printed p.13) [VC]', verified_at=now() where id='02bc9de5-429d-43c0-b912-5641e58d7d3d' and verification_status not in ('verified_against_standard','corrected');
-- M816-23.t
