-- M816-23.BW_AFA
update public.fields set verification_status='verified_against_standard', verification_quote='Alle in der Wirtschaftlichkeitsrechnung berücksichtigten Tilgungszahlungsprozesse werden in der Zusatzprojektrechnung für Gebührenzwecke dann gegen Zahlungsprozesse gemäß GI. (8a) ausgetauscht. | \mathrm{BW}_{\mathrm{AFA}}=\mathrm{AFA} \cdot \mathrm{RBF}_{0}(n ; q / p) & \tag{8b} — printed p.40', verification_note='md-verified 2026-09-05 (§4.5.3, Gl. (8b), printed p.40) [VC]', verified_at=now() where id='695e7e94-50ff-43ef-beb9-c9d15c84e9a4' and verification_status not in ('verified_against_standard','corrected');
