-- ---- M816-28 Sensitivitätsanalyse ----
-- M816-28.sensitivity_scenario
update public.fields set verification_status='verified_against_standard', verification_quote='Es macht daher Sinn, die Sensitivität des Projektbarwerts hinsichtlich von kürzeren und/oder längeren Nutzungsdauern der sensiblen Anlagenteile im Rahmen eines „Szenarios Nutzungsdauer“ zu prüfen. | Es macht also Sinn, in diesen Fällen die Projektsensitivität auf unterschiedliche Preisentwicklungen zu analysieren. Dies gilt insbesondere, bei explizit als Energieeinsparmaßnahme aufgesetzten Projekten. | Im Rahmen von Sensitivitätsanalysen sollten unter Umständen auch Kombinationen von Abweichungen mehrerer Parameter untersucht werden. — printed p.43', verification_note='md-verified 2026-09-05 (§4.6.2/§4.6.3/§4.6.4, printed p.43) [VC]', verified_at=now() where id='e0db5807-28ed-4afb-9ed7-822e8536d66e' and verification_status not in ('verified_against_standard','corrected');
