-- ============================ EQUATIONS (30) ============================
-- Gl. A.1 -> RBF_0
update public.equations set verification_status='verified_against_standard', verification_quote='Mittels des klassischen Rentenbarwertfaktors RBF( $n, q$ ) kann der Gegenwarts- oder Barwert einer regelmäßig wiederholten gleichbleibenden Zahlung, etwa einer Rente, direkt formelmäßig für eine vorgegebene Anzahl $n$ von Zahlungen und einen vorgegebenen Abzinsungssatz $i$ bzw. Abzinsungsfaktor $q$ ermittelt werden: | \operatorname{RBF}_{0}(n ; q)=\left(1-1 / q^{n}\right) /(q-1) \quad q \neq 1 \tag{A.1} — printed p.100', verification_note='md-verified 2026-09-05 (Anhang A.1, Gl. (A.1), printed p.100) [VC]', verified_at=now() where id='18a04bf4-0b37-4bba-afec-579f3bd77ab2' and verification_status <> 'verified_against_standard';
-- Gl. RBF1_rec -> RBF_1
update public.equations set verification_status='verified_against_standard', verification_quote='Das neue Instrument hat erhebliche rechentechnische Vorteile, da sich jeder Allgemeine Rentenbarwertfaktor - wie das nachstehende Berechnungsschema zeigt - rekursiv über seine Vorgänger berechnen lässt. Startpunkt ist immer der bekannte klassische Rentenbarwertfaktor. Die rekursive Ermittlung der Allgemeinen Rentenbarwertfaktoren mit den Parametern $n$ (Zeitraum in Jahresbruchteilen) und $q=1+i$ (Diskontierungsfaktor bzw. Diskontierungszinssatz) bis zum Grad $k=5$ stellt sich folgendermaßen dar: | & \operatorname{RBF}_{1}(n ; q)=\left(\operatorname{RBF}_{0}(n ; q)+1-(n+1)^{1} / q^{n}\right) /(q-1) \\ — printed p.100', verification_note='md-verified 2026-09-05 (Anhang A.1 Rekursionsschema, printed p.100) [VC]', verified_at=now() where id='fb728a50-c1e6-4068-8b61-f59eea51c73f' and verification_status <> 'verified_against_standard';
-- Gl. RBF2_rec -> RBF_2
update public.equations set verification_status='verified_against_standard', verification_quote='Das neue Instrument hat erhebliche rechentechnische Vorteile, da sich jeder Allgemeine Rentenbarwertfaktor - wie das nachstehende Berechnungsschema zeigt - rekursiv über seine Vorgänger berechnen lässt. Startpunkt ist immer der bekannte klassische Rentenbarwertfaktor. Die rekursive Ermittlung der Allgemeinen Rentenbarwertfaktoren mit den Parametern $n$ (Zeitraum in Jahresbruchteilen) und $q=1+i$ (Diskontierungsfaktor bzw. Diskontierungszinssatz) bis zum Grad $k=5$ stellt sich folgendermaßen dar: | & \operatorname{RBF}_{2}(n ; q)=\left(\operatorname{RBF}_{0}(n ; q)+2 \operatorname{RBF}_{1}(n ; q)+1-(n+1)^{2} / q^{n}\right) /(q-1) \\ — printed p.100', verification_note='md-verified 2026-09-05 (Anhang A.1 Rekursionsschema, printed p.100) [VC]', verified_at=now() where id='2f40bcaa-3fe9-49b0-a6ff-36a959a67ffb' and verification_status <> 'verified_against_standard';
-- Gl. RBF3_rec -> RBF_3
update public.equations set verification_status='verified_against_standard', verification_quote='Das neue Instrument hat erhebliche rechentechnische Vorteile, da sich jeder Allgemeine Rentenbarwertfaktor - wie das nachstehende Berechnungsschema zeigt - rekursiv über seine Vorgänger berechnen lässt. Startpunkt ist immer der bekannte klassische Rentenbarwertfaktor. Die rekursive Ermittlung der Allgemeinen Rentenbarwertfaktoren mit den Parametern $n$ (Zeitraum in Jahresbruchteilen) und $q=1+i$ (Diskontierungsfaktor bzw. Diskontierungszinssatz) bis zum Grad $k=5$ stellt sich folgendermaßen dar: | & \operatorname{RBF}_{3}(n ; q)=\left(\operatorname{RBF}_{0}(n ; q)+3 \operatorname{RBF}_{1}(n ; q)+3 \operatorname{RBF}_{2}(n ; q)+1-(n+1)^{3} / q^{n}\right) /(q-1) \\ — printed p.100', verification_note='md-verified 2026-09-05 (Anhang A.1 Rekursionsschema, printed p.100) [VC]', verified_at=now() where id='43f4db93-cba0-4bd2-a7f9-041e261e0c42' and verification_status <> 'verified_against_standard';
-- Gl. RBF4_rec -> RBF_4
update public.equations set verification_status='verified_against_standard', verification_quote='Das neue Instrument hat erhebliche rechentechnische Vorteile, da sich jeder Allgemeine Rentenbarwertfaktor - wie das nachstehende Berechnungsschema zeigt - rekursiv über seine Vorgänger berechnen lässt. Startpunkt ist immer der bekannte klassische Rentenbarwertfaktor. Die rekursive Ermittlung der Allgemeinen Rentenbarwertfaktoren mit den Parametern $n$ (Zeitraum in Jahresbruchteilen) und $q=1+i$ (Diskontierungsfaktor bzw. Diskontierungszinssatz) bis zum Grad $k=5$ stellt sich folgendermaßen dar: | & \operatorname{RBF}_{4}(n ; q)=\left(\operatorname{RBF}_{0}(n ; q)+4 \operatorname{RBF}_{1}(n ; q)+6 \operatorname{RBF}_{2}(n ; q)+4 \operatorname{RBF}_{3}(n ; q)+1-(n+1)^{4} / q^{n}\right) /(q-1) \\ — printed p.100', verification_note='md-verified 2026-09-05 (Anhang A.1 Rekursionsschema, printed p.100) [VC]', verified_at=now() where id='52f8c9ef-3f6a-4795-afd7-96179397d645' and verification_status <> 'verified_against_standard';
-- Gl. RBF5_rec -> RBF_5
update public.equations set verification_status='verified_against_standard', verification_quote='Das neue Instrument hat erhebliche rechentechnische Vorteile, da sich jeder Allgemeine Rentenbarwertfaktor - wie das nachstehende Berechnungsschema zeigt - rekursiv über seine Vorgänger berechnen lässt. Startpunkt ist immer der bekannte klassische Rentenbarwertfaktor. Die rekursive Ermittlung der Allgemeinen Rentenbarwertfaktoren mit den Parametern $n$ (Zeitraum in Jahresbruchteilen) und $q=1+i$ (Diskontierungsfaktor bzw. Diskontierungszinssatz) bis zum Grad $k=5$ stellt sich folgendermaßen dar: | & \operatorname{RBF}_{5}(n ; q)=\left(\operatorname{RBF}_{0}(n ; q)+5 \operatorname{RBF}_{1}(n ; q)+10 \operatorname{RBF}_{2}(n ; q)+10 \operatorname{RBF}_{3}(n ; q)+5 \operatorname{RBF}_{4}(n ; q)+1-(n+1)^{5} / q^{n}\right) /(q-1) — printed p.100', verification_note='md-verified 2026-09-05 (Anhang A.1 Rekursionsschema, printed p.100) [VC]', verified_at=now() where id='ce041fd9-5fa7-489c-8d1d-d9ce887fa411' and verification_status <> 'verified_against_standard';
-- Gl. 1a -> Z
update public.equations set verification_status='verified_against_standard', verification_quote='Z(t)=c_{0} \cdot t^{0}\left(=c_{0}\right) \quad t=1, \ldots, n \tag{1a} — printed p.22', verification_note='md-verified 2026-09-05 (§4.1.2, Gl. (1a), printed p.22) [VC]', verified_at=now() where id='25bc8d41-e910-4bcb-bde6-e42fca403a8d' and verification_status <> 'verified_against_standard';
-- Gl. 1b -> BW
update public.equations set verification_status='verified_against_standard', verification_quote='Für einen Zahlungsprozess vom Grad 0 ergibt sich dann als Barwert: | \mathrm{BW}=c_{0} \cdot \mathrm{RBF}_{0}(n ; q) \tag{1b} — printed p.22', verification_note='md-verified 2026-09-05 (§4.1.2, Gl. (1b), printed p.22) [VC]', verified_at=now() where id='c204cc2f-8a40-4a1c-80a8-1e3510643af5' and verification_status <> 'verified_against_standard';
-- Gl. 2a -> Z
update public.equations set verification_status='verified_against_standard', verification_quote='Lineare Zahlungsfunktionen weisen zusätzlich eine mit dem Zeitindex $t$ um einen Zahlungsbetrag $c_{1}$ anwachsende oder schrumpfende Zahlungskomponente auf. Damit liegt bezogen auf die Zeitabhängigkeit ein vom Zeitindex $t$ linear beeinflusster Zahlungsprozess vom Grade $1\left(t^{1}\right)$ vor: | Z(t)=c_{0} \cdot t^{0}+c_{1} \cdot t^{1}\left(=c_{0}+c_{1} \cdot t\right) \quad t=1, \ldots, n \tag{2a} — printed p.23', verification_note='md-verified 2026-09-05 (§4.1.3, Gl. (2a), printed p.23) [VC]', verified_at=now() where id='84c14fc4-f150-4383-ade7-43a6e6065a36' and verification_status <> 'verified_against_standard';
-- Gl. 2b -> BW
update public.equations set verification_status='verified_against_standard', verification_quote='Denn durch schematische Ersetzung der beiden Zeitterme $t^{0}$ und $t^{1}$ in Gleichung (2a) durch die gradgleichen ARBF erhält man direkt den Barwert dieser linearen Zahlungsfunktion: | \mathrm{BW}=c_{0} \cdot \mathrm{RBF}_{0}(n ; q)+c_{1} \cdot \mathrm{RBF}_{1}(n ; q) \tag{2b} — printed p.23', verification_note='md-verified 2026-09-05 (§4.1.3, Gl. (2b), printed p.23) [VC]', verified_at=now() where id='ddc3ed13-26c7-49fa-a86d-5406faa195af' and verification_status <> 'verified_against_standard';
-- Gl. 3a -> Z
update public.equations set verification_status='verified_against_standard', verification_quote='Zahlungsfunktion und Barwert ergeben sich zu | Z(t)=c_{0} \cdot t^{0}+c_{1} \cdot t^{1}+c_{2} \cdot t^{2} & t=1, \ldots, n \\ \mathrm{BW}=c_{0} \cdot \mathrm{RBF}_{0}(n ; q)+c_{1} \cdot \mathrm{RBF}_{1}(n ; q)+c_{2} \cdot \mathrm{RBF}_{2}(n ; q) — printed p.25', verification_note='md-verified 2026-09-05 (§4.1.4, printed p.25) [VC]', verified_at=now() where id='600646f1-39e6-4eb8-b749-ecf5f9f3e73a' and verification_status <> 'verified_against_standard';
-- Gl. 3b -> BW
update public.equations set verification_status='verified_against_standard', verification_quote='Zahlungsfunktion und Barwert ergeben sich zu | Z(t)=c_{0} \cdot t^{0}+c_{1} \cdot t^{1}+c_{2} \cdot t^{2} & t=1, \ldots, n \\ \mathrm{BW}=c_{0} \cdot \mathrm{RBF}_{0}(n ; q)+c_{1} \cdot \mathrm{RBF}_{1}(n ; q)+c_{2} \cdot \mathrm{RBF}_{2}(n ; q) — printed p.25', verification_note='md-verified 2026-09-05 (§4.1.4, printed p.25) [VC]', verified_at=now() where id='89a33691-c503-4649-afec-192b4b8cc172' and verification_status <> 'verified_against_standard';
-- Gl. 4a -> Z
update public.equations set verification_status='verified_against_standard', verification_quote='Zahlungsfunktion und Barwert für den allgemeinen Zahlungsprozess unter Verwendung des Summationszeichens $\sum$ für eine Summation über alle relevanten Grade $k=0,1,2, \ldots, m$ des Zahlungsprozesses lauten: | Z(t) & =c_{0} \cdot t^{0}+c_{1} \cdot t^{1}+c_{2} \cdot t^{2}+\ldots+c_{m} \cdot t^{m} \tag{4a}\\ & =\sum c_{k} \cdot t^{k} \quad t=1, \ldots, n — printed p.27', verification_note='md-verified 2026-09-05 (§4.1.5, Gl. (4a), printed p.27) [VC]', verified_at=now() where id='b57e8227-2821-4cef-b4a6-39dee062ba52' and verification_status <> 'verified_against_standard';
-- Gl. 4b -> BW
update public.equations set verification_status='verified_against_standard', verification_quote='Zahlungsfunktion und Barwert für den allgemeinen Zahlungsprozess unter Verwendung des Summationszeichens $\sum$ für eine Summation über alle relevanten Grade $k=0,1,2, \ldots, m$ des Zahlungsprozesses lauten: | B W & =\sum c_{k} \cdot R B F_{k}(n ; q) \tag{4b} — printed p.27', verification_note='md-verified 2026-09-05 (§4.1.5, Gl. (4b), printed p.27) [VC]', verified_at=now() where id='58f7825f-b1f9-40e0-87dd-3434a4b7ff58' and verification_status <> 'verified_against_standard';
-- Gl. 5a -> Z
update public.equations set verification_status='verified_against_standard', verification_quote='Formal erfolgt die Preisindexierung der einzelnen Zahlungsprozesse $Z(t)$ mittels der jeweiligen spezifischen, nominalen Preissteigerungsrate $p \%$, um dann ausgehend von der Formulierung in GI. (4a) explizit Zahlungsfunktionen mit Inflationsberücksichtigung zu erhalten: | Z(t)=\sum c_{k} \cdot t^{k} \cdot p^{t} \tag{5a} \end{equation*} $$ $$ t=1, \ldots, n \text { mit } p=1+p \% — printed p.28', verification_note='md-verified 2026-09-05 (§4.1.6, Gl. (5a), printed p.28) [VC]', verified_at=now() where id='8c53d0a6-c226-4017-8a09-1b16cb3b2489' and verification_status <> 'verified_against_standard';
-- Gl. 5b -> BW
update public.equations set verification_status='verified_against_standard', verification_quote='Der exakte Barwert mit dem genaueren Abzinsungsfaktor $q_{\text {DUR }}$ anstelle von bislang $q=1,03$ errechnet sich damit zu | \mathrm{BW}=\sum c_{\mathrm{k}} \cdot \mathrm{RBF}_{\mathrm{k}}(n ; q / p) \tag{5b} — printed p.33', verification_note='md-verified 2026-09-05 (§4.2.2, Gl. (5b), printed p.33) [VC]', verified_at=now() where id='c099c43e-009d-4b85-bfbb-376265bd4de5' and verification_status <> 'verified_against_standard';
-- Gl. 6a -> Z
update public.equations set verification_status='verified_against_standard', verification_quote='Über zusammengesetzte Zahlungsprozesse kann ein Wechsel der Funktionalität im Zeitablauf dargestellt werden. So ist zum Beispiel ein linearer Abbauprozess nach $n_{1}$ Jahren beendet und geht danach für die anschließenden $n_{2}$ Jahre in einen stabilen konstanten Prozess über. Die entsprechenden Zusammenhänge für die aus zwei Teilen bestehende Zahlungsfunktion und den Barwert lassen sich allgemein folgendermaßen angeben: | & Z(t): Z_{1}(t) \text { mit } t=1, \ldots, n_{1} \text { und nachfolgend } Z_{2}(t) \text { mit } t=n_{1}+1, \ldots, n_{1}+n_{2} \tag{6a}\\ — printed p.29', verification_note='md-verified 2026-09-05 (§4.1.7, Gl. (6a), printed p.29) [VC]', verified_at=now() where id='1681e612-af4e-44ec-b0e4-6308f36dcfba' and verification_status <> 'verified_against_standard';
-- Gl. 6b -> BW
update public.equations set verification_status='verified_against_standard', verification_quote='& \mathrm{BW}=\mathrm{BW}_{1}+1 / q^{\mathrm{n} 1} \cdot \mathrm{BW}_{2} \tag{6b} | Der Barwert des zweiten Teils weist einen Vorlauf von $n_{1}$ Jahren auf (siehe dazu auch 4.3) und muss daher um diesen Zeitraum abgezinst werden. — printed p.29', verification_note='md-verified 2026-09-05 (§4.1.7, Gl. (6b), printed p.29) [VC]', verified_at=now() where id='6ae6ac64-456d-4bce-88df-857e6c19063b' and verification_status <> 'verified_against_standard';
-- Gl. 5c -> DUR
update public.equations set verification_status='verified_against_standard', verification_quote='Die Duration DUR ergibt sich als Verhältnis von Summenprodukten aus Koeffizienten und ARBF, wobei im Zähler um einen Grad höhere Rentenbarwertfaktoren $\operatorname{RBF}_{\mathrm{k}+1}(n ; q / p), k+1=1, \ldots, m+1$ zu verwenden sind. ${ }^{11]}$ Dabei ist $q$ zunächst mit einem plausiblen Startwert, z. B. 1,03 zu belegen: | \mathrm{DUR}=\sum c_{\mathrm{k}} \cdot \mathrm{RBF}_{\mathrm{k}+1}(n ; q / p) / \sum c_{\mathrm{k}} \cdot \mathrm{RBF}_{\mathrm{k}}(n ; q / p) \tag{5c} — printed p.33', verification_note='md-verified 2026-09-05 (§4.2.2, Gl. (5c), printed p.33) [VC]', verified_at=now() where id='fb9faa7b-9c56-4188-b2a0-0d821c59a7bc' and verification_status <> 'verified_against_standard';
-- Gl. 6a_TR -> Z_TR
update public.equations set verification_status='verified_against_standard', verification_quote='Bei der Teilreplikation wird die kürzere Alternative (B) entsprechend der Nutzungsdauerdifferenz zwischen langer und kurzer Alternative teilweise repliziert. Die zusätzlich benötigten Zahlungsprozesse der Teilreplikation der kürzeren Alternative lassen sich allgemein formulieren als: | & Z_{T R}(t) ; t=1, \ldots, n_{A}-n_{B} \text { bei einem Vorlauf von } n_{B} \text { Jahren } \tag{6a}\\ — printed p.39', verification_note='md-verified 2026-09-05 (§4.4.2, Gl. (6a), printed p.39) [VC]', verified_at=now() where id='49f9a2b6-6808-45e5-890a-eca7760dac69' and verification_status <> 'verified_against_standard';
-- Gl. 6b_TR -> BW_TR
update public.equations set verification_status='verified_against_standard', verification_quote='Bei der Teilreplikation wird die kürzere Alternative (B) entsprechend der Nutzungsdauerdifferenz zwischen langer und kurzer Alternative teilweise repliziert. Die zusätzlich benötigten Zahlungsprozesse der Teilreplikation der kürzeren Alternative lassen sich allgemein formulieren als: | & \mathrm{BW}_{T R}=\left(p_{v} / q\right)^{\mathrm{nB}} \cdot \sum c_{k} \cdot \mathrm{RBF}_{k}\left(n_{A}-n_{B} ; q / p\right) \tag{6b} — printed p.39', verification_note='md-verified 2026-09-05 (§4.4.2, Gl. (6b), printed p.39) [VC]', verified_at=now() where id='1907cd42-d2fc-482a-8055-7c6b7ce92961' and verification_status <> 'verified_against_standard';
-- Gl. 6c -> DUR_TR
update public.equations set verification_status='verified_against_standard', verification_quote='Bei der Ermittlung der Duration muss nun zusätzlich der Vorlauf von $n_{\mathrm{B}}$ Jahren der kürzeren Alternative berücksichtigt werden, sodass folgt: | \mathrm{DUR}_{\mathrm{TR}}=n_{\mathrm{B}}+\sum c_{\mathrm{k}} \cdot \mathrm{RBF}_{\mathrm{k}+1} \cdot\left(n_{\mathrm{A}}-n_{\mathrm{B}} ; q / p\right) / \sum c_{\mathrm{k}} \cdot \mathrm{RBF}_{\mathrm{k}}\left(n_{\mathrm{A}}-n_{\mathrm{B}} ; q / p\right) \tag{6c} — printed p.39', verification_note='md-verified 2026-09-05 (§4.4.2, Gl. (6c), printed p.39) [VC]', verified_at=now() where id='6249bd24-2a75-456d-8227-efa601cf5613' and verification_status <> 'verified_against_standard';
-- Gl. 7 -> n_TR
update public.equations set verification_status='verified_against_standard', verification_quote='Bei teilreplizierten Finanzierungszahlungsprozessen ist die Besonderheit zu berücksichtigen, dass die Finanzierungsdauer $n_{\text {Fin }}$ regelmäßig kürzer als die Nutzungsdauern der finanzierten Investitionen ist. Daher ist die Nutzungsdauerdifferenz in den obigen Gln. (6a) bis (6c) durch eine mit dem Faktor $n_{\text {Fin }} / n_{\mathrm{B}}$ proportionalisierte Laufzeit $n_{\text {TR }}$ zu ersetzen: | n_{T R}=\left(n_{A}-n_{B}\right) \cdot n_{\text {Fin }} / n_{B} \tag{7} — printed p.39', verification_note='md-verified 2026-09-05 (§4.4.2, Gl. (7), printed p.39) [VC]', verified_at=now() where id='b188fca0-4cd9-48e8-93c2-8e0df573b9a4' and verification_status <> 'verified_against_standard';
-- Gl. 10a -> Z_ZINS
update public.equations set verification_status='verified_against_standard', verification_quote='Die Gebühreneinnahmen aus den kalkulatorischen Zinsen lassen sich dann für die $n$ Jahre der Nutzungsdauer allgemein durch folgende zeitabhängige Zahlungsfunktion | Z_{\text {ZINS }}(t)=(1-\mathrm{a}) \cdot \mathrm{RBW}_{t-1} \cdot Z_{\mathrm{K}} \quad t=1, \ldots, n \text { mit } a=\mathrm{ABK} / \mathrm{AHK} \tag{10a} — printed p.40', verification_note='md-verified 2026-09-05 (§4.5.3, Gl. (10a), printed p.40) [VC]', verified_at=now() where id='c1d04676-c630-4d10-94ac-1f520f30fe54' and verification_status <> 'verified_against_standard';
-- Gl. 10b -> Z_ZINS
update public.equations set verification_status='verified_against_standard', verification_quote='bzw. unter Verwendung von GL. (9) als zeitlinear abnehmende Zahlungsfunktion (Zeitgrad 1) darstellen. Neben der Zahlungsfunktion ergibt sich mit ARBF auch sofort der Barwert: | & Z_{\text {ZINS }}(t)=(1-a) \cdot \operatorname{AFA} \cdot z_{K} \cdot(n+1) \cdot t^{0}-(1-a) \cdot \operatorname{AFA} \cdot z_{K} \cdot t^{1} \quad t=1, \ldots, n \tag{10b}\\ — printed p.40', verification_note='md-verified 2026-09-05 (§4.5.3, Gl. (10b), printed p.40) [VC]', verified_at=now() where id='1c9610de-6f17-4e7a-bc56-78520eabf463' and verification_status <> 'verified_against_standard';
-- Gl. 10c -> BW_ZINS
update public.equations set verification_status='verified_against_standard', verification_quote='bzw. unter Verwendung von GL. (9) als zeitlinear abnehmende Zahlungsfunktion (Zeitgrad 1) darstellen. Neben der Zahlungsfunktion ergibt sich mit ARBF auch sofort der Barwert: | & \mathrm{BW}_{\text {ZINS }}=(1-a) \cdot \operatorname{AFA} \cdot z_{K} \cdot(n+1) \cdot \operatorname{RBF}_{0}(n ; q)-(1-a) \cdot \operatorname{AFA} \cdot z_{K} \cdot \operatorname{RBF}_{1}(n ; q) \tag{10c} — printed p.40', verification_note='md-verified 2026-09-05 (§4.5.3, Gl. (10c), printed p.40) [VC]', verified_at=now() where id='aa085079-0e1b-4cf6-8e30-7356c5924740' and verification_status <> 'verified_against_standard';
-- Gl. 8a -> Z_AFA
update public.equations set verification_status='verified_against_standard', verification_quote='Auf vorstehenden Grundlagen lassen sich die Gebühreneinnahmen aus kalkulatorischen Abschreibungen durch folgende zeitkonstante Zahlungsfunktion mit Inflationsberücksichtigung $p^{\dagger}$ für eine Nutzungsdauer von $n$ Jahren inklusive Barwert beschreiben | \mathrm{Z}_{\mathrm{AFA}}(t)=\mathrm{AFA} \cdot p^{\mathrm{t}} \cdot t^{0} & t=1, \ldots, n \\ — printed p.40', verification_note='md-verified 2026-09-05 (§4.5.3, Gl. (8a), printed p.40) [VC]', verified_at=now() where id='594f729c-02f9-46e7-a9b5-1c08226dd76f' and verification_status <> 'verified_against_standard';
-- Gl. 8b -> BW_AFA
update public.equations set verification_status='verified_against_standard', verification_quote='Auf vorstehenden Grundlagen lassen sich die Gebühreneinnahmen aus kalkulatorischen Abschreibungen durch folgende zeitkonstante Zahlungsfunktion mit Inflationsberücksichtigung $p^{\dagger}$ für eine Nutzungsdauer von $n$ Jahren inklusive Barwert beschreiben | \mathrm{BW}_{\mathrm{AFA}}=\mathrm{AFA} \cdot \mathrm{RBF}_{0}(n ; q / p) & \tag{8b} — printed p.40', verification_note='md-verified 2026-09-05 (§4.5.3, Gl. (8b), printed p.40) [VC]', verified_at=now() where id='ee38ba14-0229-4a5f-bc81-ae44d6aea4e6' and verification_status <> 'verified_against_standard';
-- Gl. 9 -> RBW_t
update public.equations set verification_status='verified_against_standard', verification_quote='Im Allgemeinen wird dabei der Restbuchwert RBW ${ }_{\mathrm{t}-1}$ des Vorjahres $t-1$ zugrunde gelegt (alternativ könnte auch der mittlere Restbuchwert (RBW ${ }_{t-1}+\mathrm{RBW}_{t}$ ) / 2 verwendet werden), der sich bei Abschreibungen von jeweils AFA über $n$ Nutzungsjahren ergibt zu: | \mathrm{RBW}_{\mathrm{t}-1}=\mathrm{AFA} \cdot(n+1-\mathrm{t}) \tag{9} — printed p.40', verification_note='md-verified 2026-09-05 (§4.5.3, Gl. (9), printed p.40) [VC]', verified_at=now() where id='9ee71c62-0245-4322-976c-6f7b730bf87a' and verification_status <> 'verified_against_standard';
-- Gl. 11 -> q_star
update public.equations set verification_status='verified_against_standard', verification_quote='Ein Vorteilhaftigkeitsmaßstab ist dann dafür die aus Barwerten abgeleitete Projektrendite, auch als Interne Rendite (IRR „Internal Rate of Return“) bezeichnet. ${ }^{20}$ Sie ergibt sich als derjenige Abzinsungssatz $i^{*}$ bzw. Abzinsungsfaktor $q^{*}$, bei dem die Barwerte der künftigen projektverursachten Umsatzerlöse und der künftigen Aufwendungen gleich groß sind: | \mathrm{BW}_{\text {Erlöse }}(q *)=\mathrm{BW}_{\text {Aufwendungen }}(q *) \tag{11} — printed p.42', verification_note='md-verified 2026-09-05 (§4.5.4, Gl. (11), printed p.42) [VC]', verified_at=now() where id='aeb15cc9-f182-46c4-bcfe-76ca8840f976' and verification_status <> 'verified_against_standard';

-- residue (NOT written): M816-03.price_year — no clause defines a price-base year; M816 indexes each Zahlungsprozess with its own nominal Preissteigerungsrate p% (§4.1.6) and fixes only a Bundesbank rate reference date (§4.2.1)
